export const STATUTES            = [...CORE_STATUTES, ...PACKS.flatMap((p) => p.statutes)];

export function statuteUrl(st                                  )         {
  const law = st.law.replace(/\s*\(.*$/, "").replace(/ 시행령$/, "시행령").replace(/ /g, "");
  const m = st.article.match(/제(\d+)조(의\d+)?/);
  const art = m ? `/제${m[1]}조${m[2] ?? ""}` : "";
  return `https://www.law.go.kr/법령/${law}${art}`;
}

export function findStatutes(query        , domain           , limit = 8)            {
  const q = query.trim().replace(/\s+/g, " ").toLowerCase();
  const pool = domain ? STATUTES.filter((x) => x.domain === domain) : STATUTES;
  if (!q) return pool.slice(0, limit);
  const words = q.split(" ");
  const scored = pool.map((st) => {
    const hay = [st.law, st.article, st.title, st.plain, ...st.keywords].join(" ").toLowerCase();
    let score = 0;
    for (const w of words) {
      if (st.keywords.some((k) => k.toLowerCase().includes(w) || w.includes(k.toLowerCase()))) score += 3;
      if (st.title.toLowerCase().includes(w)) score += 2;
      if (hay.includes(w)) score += 1;
    }
    return { st, score };
  });
  return scored
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((x) => x.st);
}

