export const DISCLAIMER =
  "법령 정보와 계산 도구예요. 세무대리·노무 대행·행정 대리·법률 사무를 하지 않고, 자격사 상담을 대신하지 않아요. 조문 풀이는 쉬운 말 요약이니 원문(국가법령정보센터)과 담당 기관에서 확인하세요.";

export function visibleQuestions(topic       , a         )             {
  return topic.questions.filter((q) => !q.askIf || q.askIf(a));
}

const has = (v         ) => v !== undefined && v !== null && v !== "";

export function intake(topicId        , answers          = {}, today         = LAW_GUIDE_AS_OF, limit = 3)               {
  const topic = TOPICS.find((t) => t.id === topicId);
  if (!topic) throw new Error(`unknown topic ${topicId}`);
  const a          = { ...answers, today };
  const qs = visibleQuestions(topic, a);
  const missing = qs.filter((q) => !has(answers[q.key]));
  missing.sort((x, y) => Number(!!y.required) - Number(!!x.required));
  const req = qs.filter((q) => q.required);
  const reqDone = req.filter((q) => has(answers[q.key])).length;
  const deadlines                   = [];
  for (const r of topic.deadlines) {
    if (r.when && !r.when(a)) continue;
    const from = answers[r.from];
    if (typeof from !== "string") continue;
    const d = dueDate(r, from);
    if (!d) continue;
    const left = daysBetween(today, d.due);
    deadlines.push({ id: r.id, label: r.label, due: d.due, daysLeft: left, status: left < 0 ? "passed" : left <= 14 ? "urgent" : left <= 60 ? "soon" : "ok", cite: r.cite, shifted: d.shifted, note: r.note });
  }
  deadlines.sort((x, y) => x.daysLeft - y.daysLeft);
  const prof = PROFESSIONS[topic.domain];
  return {
    topic: { id: topic.id, domain: topic.domain, label: topic.label, plain: topic.plain },
    profession: { name: prof.name, licensed: prof.licensed, act: prof.act },
    nextQuestions: missing.slice(0, limit).map(({ key, ask, why, kind, options, unit, required }) => ({ key, ask, why, kind, options, unit, required })),
    answered: qs.length - missing.length,
    total: qs.length,
    readiness: req.length ? Math.round((reqDone / req.length) * 100) : 100,
    deadlines,
    flags: topic.flags(a),
    statutes: topic.statutes.map((id) => STATUTES.find((x) => x.id === id)).filter((x)               => !!x).map((x) => ({ ...x, url: statuteUrl(x) })),
    tools: topic.tools,
    handOff: topic.handOff(a),
    documents: topic.documents,
    freeHelp: prof.freeHelp,
    disclaimer: DISCLAIMER,
  };
}

/** 상황 한 줄에서 주제를 고르는 간단한 찾기(스킬·MCP용) */
/** 상황 문장에 흔한 서술어(받았어요·했어요 등)는 주제를 가르지 못해 점수에서 빼요. */
const STOP_WORD = /^(받았|받은|했|했는데|됐|되었|있|없|싶|어떻게|어떡|해야|하나요|인가요|있나요|당했|문자로|회사에서|지금|너무|제가|저는)/;

export function suggestTopics(text        , domain           , limit = 3)                                           {
  const q = text.toLowerCase();
  const pool = domain ? TOPICS.filter((t) => t.domain === domain) : TOPICS;
  const scored = pool.map((t) => {
    const words = [t.label, t.plain, ...t.statutes.flatMap((id) => STATUTES.find((x) => x.id === id)?.keywords ?? [])].join(" ").toLowerCase();
    let score = 0;
    for (const w of q.split(/[\s,.?!·]+/).filter((x) => x.length >= 2 && !STOP_WORD.test(x))) {
      if (words.includes(w)) score += t.label.toLowerCase().includes(w) ? 1.5 : 1;
      else {
        // 2026-11-20 평가 세트에서 발견: "해고됐어요"처럼 어미·조사가 붙은 낱말은 통째로는 안 맞아요. 앞부분(2글자 이상)이 맞으면 반점만 줘요.
        for (let k = w.length - 1; k >= 2; k--) if (words.includes(w.slice(0, k))) { score += 0.5; break; }
      }
    }
    return { t, score };
  });
  return scored
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(({ t }) => ({ id: t.id, domain: t.domain, label: t.label }));
}

